const input = $json.body || $json.query || $json || {};
const headers = $json.headers || {};
const now = new Date().toISOString();
const game = String(input.target_game_code || input.game || input.target_games_csv || 'ALL').trim() || 'ALL';
const month = String(input.target_month || input.month || input.target_months_csv || 'AUTO').trim() || 'AUTO';
return [{ json: {
  central_db_id: input.central_db_id || '',
  target_game_code: game,
  target_games_csv: String(input.target_games_csv || game || 'ALL').trim() || 'ALL',
  target_month: month,
  target_months_csv: String(input.target_months_csv || month || 'AUTO').trim() || 'AUTO',
  expected_tabs_csv: input.expected_tabs_csv || 'Registered,DAU,Returners,Late_Starters,Login',
  batch_id: input.batch_id || ('BATCH-MANUAL-' + now.replace(/[-:.]/g, '').slice(0, 15) + 'Z'),
  request_id: input.request_id || ('RAW-CHECK-' + now),
  requested_by: input.requested_by || '',
  check_mode: input.check_mode || 'manual',
  source: input.source || 'cqr_admin_panel',
  webhook_received_at: now,
  request_header_secret_present: Boolean(headers['x-cqr-admin-secret'] || headers['X-CQR-Admin-Secret'])
}}];

const config = $('Set Raw Check Config').first().json;
const REPORT_START_MONTH = '2026-01';
function currentMonthKey() {
  const now = new Date();
  return now.getUTCFullYear() + '-' + String(now.getUTCMonth() + 1).padStart(2, '0');
}
function monthRange(start, end) {
  const out = [];
  let [y, m] = start.split('-').map(Number);
  const [ey, em] = end.split('-').map(Number);
  while (y < ey || (y === ey && m <= em)) {
    out.push(y + '-' + String(m).padStart(2, '0'));
    m += 1;
    if (m > 12) { m = 1; y += 1; }
  }
  return out;
}
function normalizeMonths(value) {
  const text = String(value || '').trim();
  if (!text || text.toUpperCase() === 'ALL' || text.toUpperCase() === 'AUTO') return monthRange(REPORT_START_MONTH, currentMonthKey());
  return [...new Set(text.split(',').map(v => v.trim()).filter(Boolean))];
}
const targetMonths = normalizeMonths(config.target_months_csv || config.target_month);
const targetGamesCsv = config.target_games_csv || 'ALL';
const targetGames = targetGamesCsv === 'ALL' ? null : targetGamesCsv.split(',').map(v => v.trim()).filter(Boolean);
const sourceRows = $('Read Central DB - SourceFiles').all().map(item => item.json).filter(row => !row.error);
const activeRows = sourceRows.filter(row => String(row.status || '').toLowerCase() === 'active');
const filteredRows = targetGames ? activeRows.filter(row => targetGames.includes(row.game_code)) : activeRows;
function requiredTabsFor(month) {
  return [
    { sheet_type: 'registered', tab_name: `Registered_${month}` },
    { sheet_type: 'dau', tab_name: `DAU_${month}` },
    { sheet_type: 'returners', tab_name: `Returners_${month}` },
    { sheet_type: 'late_starters', tab_name: `Late_Starters_${month}` },
    { sheet_type: 'login', tab_name: `Login_${month}` }
  ];
}
const nowKey = new Date().toISOString().replace(/[-:.]/g, '').slice(0, 15) + 'Z';
const units = [];
for (const row of filteredRows) {
  for (const targetMonth of targetMonths) {
    const requiredTabs = requiredTabsFor(targetMonth);
    units.push({ json: {
      raw_check_id: 'RAWCHK-' + row.game_code + '-' + targetMonth + '-' + nowKey,
      batch_id: config.batch_id,
      request_id: config.request_id || '',
      requested_by: config.requested_by || '',
      check_mode: config.check_mode || 'scheduled',
      request_source: config.source || '',
      central_db_id: config.central_db_id,
      game_code: row.game_code,
      period_key: targetMonth,
      target_month: targetMonth,
      raw_file_id: row.source_file_id,
      raw_file_name: row.source_file_name,
      master_file_id: row.master_file_id || '',
      required_tabs: requiredTabs,
      tab_count_expected: requiredTabs.length
    }});
  }
}
return units;

const unit = $('Prepare Raw Tab Plan').first().json;
const now = new Date().toISOString();
function rowsFrom(name) {
  try { return $(name).all().map(item => item.json).filter(row => !row.error); }
  catch (error) { return []; }
}
function errorsFrom(name) {
  try { return $(name).all().map(item => item.json).filter(row => row.error).map(row => row.error || row.message || 'read error'); }
  catch (error) { return [error.message]; }
}
function simpleHash(value) {
  const text = JSON.stringify(value);
  let hash = 0;
  for (let i = 0; i < text.length; i++) hash = ((hash << 5) - hash + text.charCodeAt(i)) | 0;
  return Math.abs(hash).toString(36);
}
function getValue(row, keys) {
  for (const key of keys) {
    if (row[key] !== undefined && row[key] !== null && String(row[key]).trim() !== '') return String(row[key]).trim();
  }
  return '';
}
function getPreviousRawHash(gameCode, periodKey) {
  let rows = [];
  try { rows = $('Read Central DB - RawIngestionLogs').all().map(item => item.json).filter(row => !row.error); }
  catch (error) { rows = []; }
  const matches = rows
    .filter(row => getValue(row, ['game_code', 'game']) === gameCode && getValue(row, ['period_key', 'month', 'target_month']) === periodKey)
    .filter(row => getValue(row, ['raw_data_hash', 'raw_updated_signal', 'hash']))
    .sort((a, b) => String(getValue(b, ['checked_at', 'created_at', 'timestamp'])).localeCompare(String(getValue(a, ['checked_at', 'created_at', 'timestamp']))));
  return matches.length ? getValue(matches[0], ['raw_data_hash', 'raw_updated_signal', 'hash']) : '';
}
const tabs = {
  registered: { tab_name: `Registered_${unit.target_month}`, rows: rowsFrom('Read Raw - Registered'), errors: errorsFrom('Read Raw - Registered') },
  dau: { tab_name: `DAU_${unit.target_month}`, rows: rowsFrom('Read Raw - DAU'), errors: errorsFrom('Read Raw - DAU') },
  returners: { tab_name: `Returners_${unit.target_month}`, rows: rowsFrom('Read Raw - Returners'), errors: errorsFrom('Read Raw - Returners') },
  late_starters: { tab_name: `Late_Starters_${unit.target_month}`, rows: rowsFrom('Read Raw - Late Starters'), errors: errorsFrom('Read Raw - Late Starters') },
  login: { tab_name: `Login_${unit.target_month}`, rows: rowsFrom('Read Raw - Login'), errors: errorsFrom('Read Raw - Login') }
};
const missingTabs = Object.entries(tabs).filter(([, tab]) => tab.errors.length || !tab.rows.length).map(([, tab]) => tab.tab_name);
const tabCountFound = Object.values(tabs).filter(tab => tab.rows.length && !tab.errors.length).length;
const RAW_HASH_PREFIX = 'v2-full:';

function stableStringify(value) {
  if (value === undefined) return '"__undefined__"';

  if (value === null || typeof value !== 'object') {
    return JSON.stringify(value);
  }

  if (Array.isArray(value)) {
    return '[' + value.map(stableStringify).join(',') + ']';
  }

  return '{' + Object.keys(value)
    .sort()
    .map(
      key =>
        JSON.stringify(key) +
        ':' +
        stableStringify(value[key])
    )
    .join(',') + '}';
}

function updateHash(hash, text) {
  const value = String(text || '');

  for (let i = 0; i < value.length; i++) {
    hash =
      ((hash << 5) - hash + value.charCodeAt(i)) | 0;
  }

  return hash;
}

let rawHashState = 0;

rawHashState = updateHash(
  rawHashState,
  unit.game_code + '|' + unit.target_month
);

for (const [tabKey, tab] of Object.entries(tabs)) {
  rawHashState = updateHash(
    rawHashState,
    '|' + tabKey + ':' + tab.rows.length + '|'
  );

  for (const row of tab.rows) {
    rawHashState = updateHash(
      rawHashState,
      stableStringify(row)
    );
  }
}

const rawDataHash =
  RAW_HASH_PREFIX +
  Math.abs(rawHashState).toString(36);
const previousRawHash = getPreviousRawHash(unit.game_code, unit.target_month);
const comparablePreviousRawHash =
  previousRawHash.startsWith(RAW_HASH_PREFIX)
    ? previousRawHash
    : '';

let status = 'raw_ready';
if (tabCountFound === 0) status = 'raw_missing';
else if (missingTabs.length) status = 'raw_partial';
else if (
  comparablePreviousRawHash &&
  comparablePreviousRawHash !== rawDataHash
) status = 'raw_updated';
const statusText = {
  raw_ready: comparablePreviousRawHash
    ? 'Raw data is unchanged: all 5 tabs match the latest Raw Check log.'
    : 'Raw data is ready: all 5 tabs were found with readable rows.',
  raw_updated: 'Raw data has changed since the latest Raw Check log. Save this result, then rebuild Master if Dashboard still shows old data.',
  raw_partial: 'Raw data needs review: some tabs are missing or empty.',
  raw_missing: 'Raw data needs review: no readable raw tabs were found.'
};
return [{ json: {
  raw_check_id: unit.raw_check_id,
  batch_id: unit.batch_id,
  request_id: unit.request_id || '',
  requested_by: unit.requested_by || '',
  check_mode: unit.check_mode || '',
  request_source: unit.request_source || '',
  game_code: unit.game_code,
  period_key: unit.target_month,
  raw_file_id: unit.raw_file_id,
  checked_at: now,
  status,
  tab_count_expected: unit.tab_count_expected,
  tab_count_found: tabCountFound,
  missing_tabs: missingTabs.join(', '),
  registered_rows: tabs.registered.rows.length,
  dau_rows: tabs.dau.rows.length,
  returners_rows: tabs.returners.rows.length,
  late_starters_rows: tabs.late_starters.rows.length,
  login_rows: tabs.login.rows.length,
  previous_raw_hash: previousRawHash,
  raw_data_hash: rawDataHash,
  raw_updated_signal: rawDataHash,
  message: statusText[status] + (missingTabs.length ? ' Missing tabs: ' + missingTabs.join(', ') : ''),
  central_db_id: unit.central_db_id,
  source_file_name: unit.raw_file_name,
  master_file_id: unit.master_file_id
}}];

const rows = $input.all().map(item => item.json);
function pick(row) {
  return {
    status: row.status,
    raw_check_id: row.raw_check_id,
    request_id: row.request_id || '',
    requested_by: row.requested_by || '',
    check_mode: row.check_mode || '',
    batch_id: row.batch_id,
    game_code: row.game_code,
    period_key: row.period_key,
    tab_count_found: row.tab_count_found,
    tab_count_expected: row.tab_count_expected,
    missing_tabs: row.missing_tabs || '',
    registered_rows: row.registered_rows,
    dau_rows: row.dau_rows,
    returners_rows: row.returners_rows,
    late_starters_rows: row.late_starters_rows,
    login_rows: row.login_rows,
    previous_raw_hash: row.previous_raw_hash || '',
    raw_data_hash: row.raw_data_hash,
    message: row.message
  };
}
if (rows.length <= 1) return [{ json: pick(rows[0] || {}) }];
const counts = rows.reduce((acc, row) => {
  const status = row.status || 'unknown';
  acc[status] = (acc[status] || 0) + 1;
  return acc;
}, {});
const status = counts.raw_missing || counts.raw_partial
  ? 'raw_partial'
  : counts.raw_updated
    ? 'raw_updated'
    : 'raw_ready';
return [{ json: {
  status,
  scope_count: rows.length,
  raw_ready_count: counts.raw_ready || 0,
  raw_updated_count: counts.raw_updated || 0,
  raw_partial_count: (counts.raw_partial || 0) + (counts.raw_missing || 0),
  batch_id: rows[0]?.batch_id || '',
  request_id: rows[0]?.request_id || '',
  check_mode: rows[0]?.check_mode || '',
  message: status === 'raw_ready'
    ? 'Raw check completed: every selected game/month is readable and unchanged.'
    : status === 'raw_updated'
      ? 'Raw check completed: some selected game/month data changed since the latest Raw Check log.'
      : 'Raw check completed: some selected game/month data is missing or incomplete.',
  results: rows.map(pick)
}}];

